vulnerable_code:
app.post('/api/profile/upsert', async (req, res) => {
  const result = await Profile.findOneAndUpdate(
    { id: req.body.id },
    req.body,
    { upsert: true }
  );
  res.json(result);
});

corrected_code:
app.post('/api/profile/upsert', async (req, res) => {
  const result = await Profile.findOneAndUpdate(
    { id: req.body.id, ownerId: req.user.id },
    req.body,
    { upsert: true }
  );
  res.json(result);
});
